const winston = require('winston');
const path = require('path');
const fs = require('fs');

// Ensure logs directory exists
const logsDir = path.join(process.cwd(), 'logs');
if (!fs.existsSync(logsDir)) {
  fs.mkdirSync(logsDir, { recursive: true });
}

// Define custom format with colors for console
const consoleFormat = winston.format.combine(
  winston.format.colorize(),
  winston.format.timestamp(),
  winston.format.printf(({ level, message, timestamp, ...rest }) => {
    // If message is an object, stringify it for display
    let formattedMessage = message;
    
    // Handle case where the entire message is an object
    if (typeof message === 'object' && message !== null) {
      formattedMessage = JSON.stringify(message, null, 2);
    }
    
    // Include additional properties if they exist
    const additionalInfo = Object.keys(rest).length > 0 
      ? ` ${JSON.stringify(rest, null, 2)}`
      : '';
      
    return `${timestamp} ${level}: ${formattedMessage}${additionalInfo}`;
  })
);

// Define format for file logs
const fileFormat = winston.format.combine(
  winston.format.timestamp(),
  winston.format.json()
);

// Create the logger instance
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  levels: winston.config.npm.levels,
  format: fileFormat,
  defaultMeta: { service: 'subsafe' },
  transports: [
    // Write logs to console
    new winston.transports.Console({
      format: consoleFormat
    }),
    // Write all logs with level 'error' and below to errors.log
    new winston.transports.File({ 
      filename: path.join(logsDir, 'error.log'), 
      level: 'error'
    }),
    // Write all logs with level 'info' and below to combined.log
    new winston.transports.File({ 
      filename: path.join(logsDir, 'combined.log')
    })
  ]
});

// Capture logs for UI display (last 50 entries)
const logHistory = [];

// Create a custom transport to capture logs for UI display
class MemoryTransport extends winston.Transport {
  constructor(options = {}) {
    super(options);
    this.name = 'memory';
    this.level = options.level || 'info';
  }

  log(info, callback) {
    setImmediate(() => {
      this.emit('logged', info);
    });

    try {
      // Format message if it's an object
      let formattedMessage = info.message;
      if (typeof info.message === 'object' && info.message !== null) {
        formattedMessage = JSON.stringify(info.message, null, 2);
      }
      
      // Add to log history (limited to last 50 entries)
      logHistory.unshift({
        message: formattedMessage,
        level: info.level,
        timestamp: info.timestamp || Date.now(),
        time: info.timestamp ? new Date(info.timestamp).toISOString() : new Date().toISOString()
      });
      
      // Limit history to 50 entries
      if (logHistory.length > 50) {
        logHistory.splice(50);
      }
    } catch (err) {
      console.error('Error in memory transport:', err);
    }

    callback();
  }
}

// Add the memory transport
logger.add(new MemoryTransport({
  level: 'debug'
}));

// Get the log history
logger.getLogHistory = () => {
  return logHistory;
};

module.exports = logger; 